observation.command:
cat > /tmp/render-test.mjs <<'EOF'
import { chromium } from '/workspace/node_modules/@playwright/test/index.js';

const browser = await chromium.launch({ args: ['--no-sandbox'] });
const page = await browser.newPage();
const errors = [];
page.on('pageerror', e => errors.push('PAGEERROR: ' + e.message));
page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE: ' + m.text()); });

await page.goto('http://localhost:5173/', { waitUntil: 'networkidle', timeout: 60000 });
await page.waitForTimeout(3000);

const title = await page.title();
const rootHtml = await page.evaluate(() => document.getElementById('root')?.innerHTML?.length ?? 0);
const bodyText = (await page.evaluate(() => document.body.innerText)).slice(0, 400);
console.log('TITLE:', title);
console.log('ROOT_HTML_LENGTH:', rootHtml);
console.log('BODY_TEXT_START:', JSON.stringify(bodyText));
console.log('ERRORS:', errors.length ? errors.slice(0, 10).join(' | ') : 'none');
await browser.close();
EOF
node /tmp/render-test.mjs; echo "TEST EXIT: $?"
